    int? dry=null,red=null,blem=null;if(!Tracking.CanEdit(date,DateTime.Now)){error.Text="Bu günün kayıt penceresi kapandı.";return;}
    if(skin&&(!Score(dryness.Text,out dry)||!Score(redness.Text,out red)||!Score(blemishes.Text,out blem))){error.Text="Puanları boş bırak veya 0–5 arasında yaz.";return;}
    Value=new RoutineRecord{Date=Tracking.Key(date),Group=group,Status=(string)state.SelectedItem,Note=note.Text.Trim(),ProductIds=checks.Where(c=>c.Value.IsChecked==true).Select(c=>c.Key.Id).ToList(),Dryness=dry,Redness=red,Blemishes=blem};DialogResult=true;
   },true);save.Name="SaveRoutineRecord";panel.Children.Add(save);
  }
  static bool Score(string text,out int? value){value=null;if(string.IsNullOrWhiteSpace(text))return true;int x;if(!int.TryParse(text,out x)||x<0||x>5)return false;value=x;return true;}
 }
 public class ProductEditor:Window {
