  public ProductEditor(Window owner,SkinProduct product){Owner=owner;Title="Ürün kaydı";Width=460;Height=570;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=UI.B(UI.PageBackground);FontFamily=UI.AppFont;var panel=new StackPanel{Margin=new Thickness(24)};Content=panel;panel.Children.Add(UI.Text("Güncel ürünüm",24));panel.Children.Add(UI.Text("Ürün adı",13,UI.Muted));var name=UI.Input(product==null?"":product.Name,160);panel.Children.Add(name);panel.Children.Add(UI.Text("Ürün türü",13,UI.Muted));var category=new ComboBox{FontSize=16,Padding=new Thickness(8),Margin=new Thickness(0,6,0,12)};foreach(var s in ProductKnowledge.Categories)category.Items.Add(s);category.SelectedItem=product==null?"Diğer":product.Category;if(category.SelectedIndex<0)category.SelectedIndex=category.Items.Count-1;panel.Children.Add(category);panel.Children.Add(UI.Text("Etiketteki içerikler isteğe bağlı",13,UI.Muted));var ingredients=UI.Input(product==null?"":product.Ingredients,700);ingredients.Height=75;ingredients.TextWrapping=TextWrapping.Wrap;panel.Children.Add(ingredients);var started=new DatePicker{SelectedDate=product==null?DateTime.Today:ParseDate(product.Started),FontFamily=UI.AppFont,FontSize=15,Margin=new Thickness(0,4,0,10)};panel.Children.Add(UI.Text("Kullanmaya başladığım tarih",13,UI.Muted));panel.Children.Add(started);var active=UI.Check("Şu anda kullanıyorum",product==null||product.Active);panel.Children.Add(active);panel.Children.Add(UI.Button("Ürünü kaydet",()=>{if(string.IsNullOrWhiteSpace(name.Text))return;Value=new SkinProduct{Name=name.Text.Trim(),Category=(string)category.SelectedItem,Ingredients=ingredients.Text.Trim(),Started=Tracking.Key(started.SelectedDate??DateTime.Today),Active=active.IsChecked==true};DialogResult=true;},true));}
  static DateTime ParseDate(string s){DateTime date;return DateTime.TryParse(s,out date)?date:DateTime.Today;}
 }
